-- Ne Var Ne Yok hesapları. Cloudflare D1 → veritabanı → Console'a yapıştırılır.
CREATE TABLE IF NOT EXISTS kisi (id INTEGER PRIMARY KEY AUTOINCREMENT, gid TEXT NOT NULL UNIQUE, ad TEXT UNIQUE, gorunen TEXT NOT NULL DEFAULT '', gizli INTEGER NOT NULL DEFAULT 1, rol TEXT NOT NULL DEFAULT 'uye', beta INTEGER NOT NULL DEFAULT 0, olusma INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS takip (kim INTEGER NOT NULL, kimi INTEGER NOT NULL, durum TEXT NOT NULL, zaman INTEGER NOT NULL, PRIMARY KEY (kim, kimi));
CREATE INDEX IF NOT EXISTS takip_kimi ON takip (kimi, durum);
CREATE TABLE IF NOT EXISTS engel (kim INTEGER NOT NULL, kimi INTEGER NOT NULL, PRIMARY KEY (kim, kimi));
CREATE TABLE IF NOT EXISTS ayar (k TEXT PRIMARY KEY, v TEXT NOT NULL);
